-- SANDBOX delta for UpsRate (PARTIAL), generated by diffing the production (azuredb01) and SANDBOX inventories
-- taken on 2026-10-22. Schema only; no data is copied. For review before it is applied to SANDBOX.
-- Idempotent. Refuses to run anywhere except SANDBOX. ONE batch (no GO) so the guard stops everything.
--
-- NOT covered yet: stored procedures GetPlantCharges and VerifyAndCorrect_PO_ZipCode, and column defaults.
-- The production inventory login could not see any stored procedure or default constraint (no VIEW DEFINITION),
-- so those could not be compared. Re-run inventory.sql on production with a login that can see definitions.
--
-- Differences found in tables the app (or GetPlantCharges) uses:
--   Plants: missing GLCode (int NOT NULL), UpsShippingNumber (nchar(20) NULL), and primary key PK_Plants.
--   PlantCarrierCharges2017: missing Active (varchar(1) NULL). (numeric vs decimal on the rate columns is the
--     same type in SQL Server and is left alone.)
--   CarrierApiCall, CarrierRateQuote, PiedmontAcctsForSpecialAlpRates: no visible differences.

IF @@SERVERNAME <> 'SANDBOX' THROW 50030, 'Refusing to run: not connected to SANDBOX.', 1;

IF DB_NAME() <> 'UpsRate' THROW 50031, 'Refusing to run: connect to the UpsRate database.', 1;

-- Plants
IF COL_LENGTH('dbo.Plants', 'UpsShippingNumber') IS NULL
    ALTER TABLE dbo.Plants ADD UpsShippingNumber nchar(20) NULL;

-- Production's GLCode is NOT NULL with no default. SANDBOX's existing rows need a value to satisfy that, so they
-- get 0 as a placeholder (the default is dropped straight after, matching production). Review: if you would
-- rather keep SANDBOX's rows honest, make this column NULL instead; the app does not read it.
IF COL_LENGTH('dbo.Plants', 'GLCode') IS NULL
BEGIN
    ALTER TABLE dbo.Plants ADD GLCode int NOT NULL CONSTRAINT DF_Plants_GLCode_tmp DEFAULT (0);
    ALTER TABLE dbo.Plants DROP CONSTRAINT DF_Plants_GLCode_tmp;
END

IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID('dbo.Plants') AND name = 'PK_Plants')
BEGIN
    IF EXISTS (SELECT PlantCode FROM dbo.Plants GROUP BY PlantCode HAVING COUNT(*) > 1)
        THROW 50032, 'Cannot add PK_Plants: duplicate PlantCode values exist in SANDBOX dbo.Plants.', 1;
    ALTER TABLE dbo.Plants ADD CONSTRAINT PK_Plants PRIMARY KEY CLUSTERED (PlantCode);
END

-- PlantCarrierCharges2017
IF COL_LENGTH('dbo.PlantCarrierCharges2017', 'Active') IS NULL
    ALTER TABLE dbo.PlantCarrierCharges2017 ADD Active varchar(1) NULL;
